code_example:
typedef struct {
    void *resource;
    int *ref_count;
    void (*release)(void *);
} SharedResource;

SharedResource *shared_create(void *res, void (*release_func)(void *)) {
    SharedResource *sr = malloc(sizeof(SharedResource));
    sr->resource = res;
    sr->ref_count = malloc(sizeof(int));
    *(sr->ref_count) = 1;
    sr->release = release_func;
    return sr;
}

void shared_acquire(SharedResource *sr) {
    (*(sr->ref_count))++;
}

void shared_release(SharedResource *sr) {
    if (--(*(sr->ref_count)) == 0) {
        sr->release(sr->resource);
        free(sr->ref_count);
        free(sr);
    }
}
